SELECT id, recipient_id, sender_id, sender_username, sender_avatar, type,
       post_id, comment_id, content, is_read, create_time, update_time
FROM tb_system_notification


        AND recipient_id = #{recipientId}


        AND sender_id = #{senderId}


        AND type = #{type}


        AND is_read = #{isRead}


        AND post_id = #{postId}


ORDER BY create_time DESC

SELECT COUNT(*) FROM tb_system_notification
WHERE recipient_id = #{recipientId}
AND is_read = 0
AND type = #{type}
